<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $data = ["fields" => [["font_family" => "niconne"]]]; $rules = ["fields.*.font_family" => ["sometimes", "in:helvetica,times,georgia,montserrat,poppins,playfair,dancing-script,great-vibes,niconne"]]; $validator = Illuminate\Support\Facades\Validator::make($data, $rules); echo $validator->fails() ? "FAILS: " . json_encode($validator->errors()) : "PASSES"; echo "\n";
